package com.multistreamcammc.client; import com.multistreamcammc.MultiStreamCamMCMod;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.minecraft.client.gui.screen.Screen;import net.minecraft.client.gui.widget.ButtonWidget;import net.minecraft.network.PacketByteBuf;import net.minecraft.text.Text;import java.util.*; public class CameraQuickMenuScreen extends Screen{private final List<ClientCameraEntry> cams;protected CameraQuickMenuScreen(List<ClientCameraEntry> c){super(Text.literal("MultiStreamCamMC"));cams=c;}protected void init(){int y=24;for(var c:cams){addDrawableChild(ButtonWidget.builder(Text.literal(c.label()),b->go(c.name())).dimensions(width/2-140,y,280,20).build());y+=24;if(y>height-40)break;}}private void go(String n){PacketByteBuf b=PacketByteBufs.create();b.writeString(n);ClientPlayNetworking.send(MultiStreamCamMCMod.CAMERA_GOTO_PACKET,b);close();}}
